                INT16 shift1D = (SCALE_MASK & index1D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift2D = (SCALE_MASK & index2D) >> (SCALE_BITS - SHIFT_BITS);
                INT16 shift3D = (SCALE_MASK & index3D) >> (SCALE_BITS - SHIFT_BITS);
                int idx = table_channels * table_index3D(
                                                   index1D >> SCALE_BITS,
                                                   index2D >> SCALE_BITS,
                                                   index3D >> SCALE_BITS,
                                                   size1D,
                                                   size1D_2D);

                __m128i c000 = load_corner4(&table[idx]);
                __m128i c100 = load_corner4(&table[idx + 4]);
                __m128i c010 = load_corner4(&table[idx + stride_1D]);
                __m128i c110 = load_corner4(&table[idx + stride_1D + 4]);
                __m128i c001 = load_corner4(&table[idx + stride_2D]);
                __m128i c101 = load_corner4(&table[idx + stride_2D + 4]);
                __m128i c011 = load_corner4(&table[idx + stride_2D + stride_1D]);
                __m128i c111 = load_corner4(&table[idx + stride_2D + stride_1D + 4]);

