                __m128i s2D = _mm_set1_epi32(shift2D);
                __m128i s3D = _mm_set1_epi32(shift3D);

                __m128i leftleft  = lerp_sse(c000, c100, s1D);
                __m128i leftright = lerp_sse(c010, c110, s1D);
                __m128i left      = lerp_sse(leftleft, leftright, s2D);

                __m128i rightleft  = lerp_sse(c001, c101, s1D);
                __m128i rightright = lerp_sse(c011, c111, s1D);
                __m128i right      = lerp_sse(rightleft, rightright, s2D);

                __m128i result = lerp_sse(left, right, s3D);

