import numpy as np
from PIL import Image, ImageFilter

np.random.seed(9999)
width, height = 100, 100

# Test with various LUT sizes and transforms
for size in [3, 17, 33]:
    for channels in [3, 4]:
        def make_transform():
            return lambda r, g, b: (
                (r * 0.8 + g * 0.1 + b * 0.1) if channels == 3 else 
                (r * 0.8 + g * 0.1 + b * 0.1, g, b, 1.0)
            ) if channels == 4 else (
                r * 0.8 + g * 0.1 + b * 0.1, g, b
            )

        if channels == 4:
            img = Image.fromarray(np.random.randint(0, 256, (width, height, 4), dtype=np.uint8), 'RGBA')
            def t(r, g, b):
                return (r * 0.8 + g * 0.1 + b * 0.1, g, b, 1.0)
        else:
            img = Image.fromarray(np.random.randint(0, 256, (width, height, 3), dtype=np.uint8), 'RGB')
            def t(r, g, b):
                return (r * 0.8 + g * 0.1 + b * 0.1, g, b)

        lut = ImageFilter.Color3DLUT.generate(size, t, channels=channels)
        result = img.filter(lut)
        arr = np.array(result)

        # Verify valid output
        assert arr.min() >= 0 and arr.max() <= 255, f'Range error: [{arr.min()}, {arr.max()}]'
        assert result.size == (width, height), f'Size error: {result.size}'

        print(f'  size={size}, ch={channels}: OK (avg={arr.mean(axis=(0,1)).round(2)})')

print('All correctness tests passed!')
" 2>&1

